# owner: platform
"""Contact sheet for substitute teachers."""

from typing import List

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _align(rows: List[tuple]) -> List[str]:
    widths = [max(len(cell) for cell in col) for col in zip(*rows)]
    return [
        "  ".join(cell.ljust(wide) for cell, wide in zip(row, widths)).rstrip()
        for row in rows
    ]


def _check(students: List[Student]) -> None:
    if not students:
        raise ProjectError("no students to list")
    for student in students:
        if not student.email:
            raise ProjectError(f"no email for {student.display_name}")


# ---
def contact_rows(students: List[Student]) -> List[str]:
    _check(students)
    ordered = sorted(students, key=lambda item: item.display_name)
    return _align([(one.display_name, one.section, one.email) for one in ordered])

