# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.errors import ProjectError
from rosterkit.contacts import contact_rows


def _student(last, first, email="a@x.org"):
    return Student("id1", last, first, "B2", email)


class ContactTests(unittest.TestCase):
    def test_sorted_and_aligned(self):
        rows = contact_rows([_student("Zed", "Al"), _student("Abe", "Bo", "bo@x.org")])
        self.assertEqual(rows[0], "Abe, Bo  B2  bo@x.org")
        self.assertEqual(rows[1], "Zed, Al  B2  a@x.org")

    def test_missing_email_names_student(self):
        with self.assertRaisesRegex(ProjectError, "Zed, Al"):
            contact_rows([_student("Zed", "Al", None)])

    def test_empty_list(self):
        with self.assertRaises(ProjectError):
            contact_rows([])
